#include <iostream>
struct Base {
    virtual void id() const { std::cout << "Base"; }
};
struct Derived : Base {
    void id() const override { std::cout << "Derived"; }
};
void printId(Base b) { b.id(); }
int main() {
    Derived d;
    printId(d);
}

